#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <cstring>
#include <functional>
#include <stdexcept>

namespace auth {

// Unicode normalization table for common confusables
struct NormEntry {
    uint32_t codepoint;
    uint32_t canonical;
};

static const NormEntry CONFUSABLE_TABLE[] = {
    {0x0410, 'A'},  // Cyrillic А -> Latin A
    {0x0412, 'B'},  // Cyrillic В -> Latin B
    {0x0421, 'C'},  // Cyrillic С -> Latin C
    {0x0415, 'E'},  // Cyrillic Е -> Latin E
    {0x041D, 'H'},  // Cyrillic Н -> Latin H
    {0x041A, 'K'},  // Cyrillic К -> Latin K
    {0x041C, 'M'},  // Cyrillic М -> Latin M
    {0x041E, 'O'},  // Cyrillic О -> Latin O
    {0x0420, 'P'},  // Cyrillic Р -> Latin P
    {0x0422, 'T'},  // Cyrillic Т -> Latin T
    {0x0425, 'X'},  // Cyrillic Х -> Latin X
    {0x0430, 'a'},  // Cyrillic а -> Latin a
    {0x0435, 'e'},  // Cyrillic е -> Latin e
    {0x043E, 'o'},  // Cyrillic о -> Latin o
    {0x0440, 'p'},  // Cyrillic р -> Latin p
    {0x0441, 'c'},  // Cyrillic с -> Latin c
    {0x0443, 'y'},  // Cyrillic у -> Latin y
    {0x0445, 'x'},  // Cyrillic х -> Latin x
};

static const size_t CONFUSABLE_COUNT = sizeof(CONFUSABLE_TABLE) / sizeof(NormEntry);

// Decode a single UTF-8 codepoint, advance iterator
static uint32_t decode_utf8(const char*& it, const char* end) {
    uint32_t cp = 0;
    unsigned char c = static_cast<unsigned char>(*it);
    if (c < 0x80) {
        cp = c; it++;
    } else if ((c & 0xE0) == 0xC0) {
        cp = c & 0x1F;
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        it++;
    } else if ((c & 0xF0) == 0xE0) {
        cp = c & 0x0F;
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        it++;
    } else if ((c & 0xF8) == 0xF0) {
        cp = c & 0x07;
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        if (++it < end) cp = (cp << 6) | (static_cast<unsigned char>(*it) & 0x3F);
        it++;
    } else {
        it++;
    }
    return cp;
}

// Normalize a single codepoint against confusable table
static uint32_t normalize_codepoint(uint32_t cp) {
    for (size_t i = 0; i < CONFUSABLE_COUNT; i++) {
        if (CONFUSABLE_TABLE[i].codepoint == cp) {
            return CONFUSABLE_TABLE[i].canonical;
        }
    }
    return cp;
}

// Check if a string contains mixed scripts (security check)
static bool is_mixed_script(const std::string& input) {
    bool has_latin = false;
    bool has_cyrillic = false;
    const char* it = input.c_str();
    const char* end = it + input.size();
    while (it < end) {
        uint32_t cp = decode_utf8(it, end);
        if ((cp >= 0x0041 && cp <= 0x005A) || (cp >= 0x0061 && cp <= 0x007A))
            has_latin = true;
        if (cp >= 0x0400 && cp <= 0x04FF)
            has_cyrillic = true;
    }
    return has_latin && has_cyrillic;
}

// Canonicalize a service principal name for comparison
static std::string canonicalize_principal(const std::string& principal) {
    std::string result;
    const char* it = principal.c_str();
    const char* end = it + principal.size();
    while (it < end) {
        uint32_t cp = decode_utf8(it, end);
        uint32_t norm = normalize_codepoint(cp);
        if (norm < 0x80) {
            result += static_cast<char>(norm);
        } else {
            // Re-encode as UTF-8
            if (norm < 0x800) {
                result += static_cast<char>(0xC0 | (norm >> 6));
                result += static_cast<char>(0x80 | (norm & 0x3F));
            } else {
                result += static_cast<char>(0xE0 | (norm >> 12));
                result += static_cast<char>(0x80 | ((norm >> 6) & 0x3F));
                result += static_cast<char>(0x80 | (norm & 0x3F));
            }
        }
    }
    return result;
}

class ServiceAuthenticator {
private:
    struct ServiceEntry {
        std::string canonical_name;
        std::string token_hash;
        int trust_level;
    };

    std::vector<ServiceEntry> registered_services_;

    // Internal lookup: finds service by canonical name match
    const ServiceEntry* find_service(const std::string& canonical) const {
        for (const auto& entry : registered_services_) {
            if (entry.canonical_name == canonical)
                return &entry;
        }
        return nullptr;
    }

public:
    void register_service(const std::string& name, const std::string& token_hash, int trust_level) {
        // Registration always uses canonical form
        ServiceEntry entry;
        entry.canonical_name = canonicalize_principal(name);
        entry.token_hash = token_hash;
        entry.trust_level = trust_level;
        registered_services_.push_back(entry);
    }

    // Authenticate a cross-service request
    // Returns trust_level on success, -1 on failure
    int authenticate_request(const std::string& claimed_service, const std::string& token) {
        // Phase 1: Script mixing detection (security layer)
        // Only reject if the name has MIXED scripts - pure Cyrillic or pure Latin is allowed
        if (is_mixed_script(claimed_service)) {
            return -1;  // Reject mixed-script names as suspicious
        }

        // Phase 2: Canonicalize and lookup
        std::string canonical = canonicalize_principal(claimed_service);
        const ServiceEntry* service = find_service(canonical);
        if (!service) {
            return -1;
        }

        // Phase 3: Token verification (simplified for demonstration)
        std::hash<std::string> hasher;
        std::string computed = std::to_string(hasher(token));
        if (computed != service->token_hash) {
            return -1;
        }

        return service->trust_level;
    }
};

} // namespace auth
